-- =============================================================================
-- Copay: Portfolio 1 schema (PostgreSQL 16)
-- MIT 8103 Advanced Database Systems
--
-- Run:  psql -v ON_ERROR_STOP=1 -f schema.sql
-- WARNING: this script drops and recreates the public schema. It is meant for
-- the local Docker database only.
--
-- Design choices (details in README.md and normalisation.md):
--  * bigint identity keys: compact, ordered, fast joins. GENERATED BY DEFAULT is
--    used (not ALWAYS) so the seed generator can load explicit ids with COPY and
--    keep foreign keys consistent. The sequences are reset after loading.
--  * Money is NUMERIC(14,2) in NGN. Never floating point.
--  * Native ENUM types for status columns: self documenting, 4 bytes, validated.
--  * Business rules live in the database (CHECK, UNIQUE, triggers) so that no
--    application bug or manual SQL session can break them.
--  * Only indexes needed for integrity are created here. Performance indexes are
--    added in Portfolio 2 so that the "before" query plans are meaningful.
-- =============================================================================

DROP SCHEMA IF EXISTS public CASCADE;
CREATE SCHEMA public;

-- -----------------------------------------------------------------------------
-- 1. Enumerated types
-- -----------------------------------------------------------------------------
CREATE TYPE user_role         AS ENUM ('USER', 'SUPPORT', 'ADMIN');
CREATE TYPE user_status       AS ENUM ('ACTIVE', 'SUSPENDED', 'CLOSED');
CREATE TYPE kyc_status        AS ENUM ('NOT_STARTED', 'PENDING', 'VERIFIED', 'REJECTED');
CREATE TYPE wallet_kind       AS ENUM ('USER', 'ESCROW', 'FEES', 'EXTERNAL');
CREATE TYPE request_status    AS ENUM ('OPEN', 'FUNDED', 'CANCELLED', 'EXPIRED');
CREATE TYPE loan_status       AS ENUM ('ACTIVE', 'REPAID', 'DEFAULTED');
CREATE TYPE instalment_status AS ENUM ('PENDING', 'PARTIAL', 'PAID', 'OVERDUE');
CREATE TYPE txn_type          AS ENUM ('WALLET_FUNDING', 'WALLET_WITHDRAWAL', 'LOAN_FUNDING',
                                       'DISBURSEMENT', 'REPAYMENT', 'WALLET_TRANSFER');
CREATE TYPE dispute_status    AS ENUM ('OPEN', 'UNDER_REVIEW', 'RESOLVED', 'REJECTED');
CREATE TYPE notification_type AS ENUM ('LOAN_FUNDED', 'REPAYMENT_RECEIVED', 'REPAYMENT_DUE',
                                       'KYC_UPDATE', 'SYSTEM');

-- Business constant: KYC verification is required to lend or borrow above this.
CREATE FUNCTION copay_kyc_limit() RETURNS numeric
    LANGUAGE sql IMMUTABLE AS $$ SELECT 100000.00::numeric $$;

-- -----------------------------------------------------------------------------
-- 2. Identity and KYC
-- -----------------------------------------------------------------------------
CREATE TABLE users (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email       text        NOT NULL UNIQUE,
    phone       text        NOT NULL UNIQUE,
    full_name   text        NOT NULL,
    role        user_role   NOT NULL DEFAULT 'USER',
    status      user_status NOT NULL DEFAULT 'ACTIVE',
    created_at  timestamptz NOT NULL DEFAULT now(),
    deleted_at  timestamptz,                       -- soft delete
    CONSTRAINT users_email_lowercase CHECK (email = lower(email)),
    CONSTRAINT users_email_shape     CHECK (email LIKE '%_@_%.__%'),
    CONSTRAINT users_phone_shape     CHECK (phone ~ '^\+234[0-9]{10}$')
);

CREATE TABLE kyc_profiles (
    user_id      bigint     PRIMARY KEY REFERENCES users (id),
    status       kyc_status NOT NULL DEFAULT 'NOT_STARTED',
    level        smallint   NOT NULL DEFAULT 0 CHECK (level BETWEEN 0 AND 3),
    bvn_hash     text,                              -- hash only, never the raw BVN
    submitted_at timestamptz,
    verified_at  timestamptz,
    CONSTRAINT kyc_verified_has_date CHECK (status <> 'VERIFIED' OR verified_at IS NOT NULL),
    CONSTRAINT kyc_verified_has_level CHECK (status <> 'VERIFIED' OR level >= 1)
);

CREATE FUNCTION copay_is_kyc_verified(p_user_id bigint) RETURNS boolean
    LANGUAGE sql STABLE AS
$$ SELECT EXISTS (SELECT 1 FROM kyc_profiles WHERE user_id = p_user_id AND status = 'VERIFIED') $$;

-- -----------------------------------------------------------------------------
-- 3. Wallets and bank accounts
-- -----------------------------------------------------------------------------
-- Every user has one wallet. Three system wallets exist so that every movement of
-- money has a counterparty (double entry):
--   EXTERNAL : the outside world (bank). Its balance is minus the net cash that
--              entered Copay, so it is the only wallet allowed to be negative.
--   ESCROW   : money pledged by lenders until a request is fully funded.
--   FEES     : Copay's service fee income.
CREATE TABLE wallets (
    id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id    bigint REFERENCES users (id),
    kind       wallet_kind   NOT NULL DEFAULT 'USER',
    currency   char(3)       NOT NULL DEFAULT 'NGN' CHECK (currency = 'NGN'),
    -- Deliberate denormalisation: cached sum of ledger_entries.amount, maintained
    -- by trigger and verified by the wallet_reconciliation view.
    balance    numeric(14,2) NOT NULL DEFAULT 0,
    version    integer       NOT NULL DEFAULT 0,    -- optimistic locking (Portfolio 3)
    created_at timestamptz   NOT NULL DEFAULT now(),
    updated_at timestamptz   NOT NULL DEFAULT now(),
    CONSTRAINT wallets_balance_non_negative CHECK (kind = 'EXTERNAL' OR balance >= 0),
    CONSTRAINT wallets_owner_matches_kind   CHECK ((kind = 'USER') = (user_id IS NOT NULL))
);
CREATE UNIQUE INDEX wallets_one_per_user ON wallets (user_id) WHERE kind = 'USER';
CREATE UNIQUE INDEX wallets_one_per_system_kind ON wallets (kind) WHERE kind <> 'USER';

CREATE TABLE bank_accounts (
    id             bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id        bigint      NOT NULL REFERENCES users (id),
    bank_code      char(3)     NOT NULL,
    account_number char(10)    NOT NULL CHECK (account_number ~ '^[0-9]{10}$'),
    account_name   text        NOT NULL,
    is_primary     boolean     NOT NULL DEFAULT false,
    created_at     timestamptz NOT NULL DEFAULT now(),
    deleted_at     timestamptz,
    UNIQUE (user_id, bank_code, account_number)
);

-- -----------------------------------------------------------------------------
-- 4. Ledger (double entry, append only)
-- -----------------------------------------------------------------------------
CREATE TABLE ledger_transactions (
    id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    txn_type        txn_type    NOT NULL,
    reference       text        NOT NULL UNIQUE,
    description     text,
    idempotency_key text        UNIQUE,            -- NULL allowed, duplicates not
    created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE ledger_entries (
    id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    txn_id     bigint        NOT NULL REFERENCES ledger_transactions (id),
    wallet_id  bigint        NOT NULL REFERENCES wallets (id),
    amount     numeric(14,2) NOT NULL CHECK (amount <> 0),   -- + credit, - debit
    created_at timestamptz   NOT NULL DEFAULT now()
);
-- Required by the balancing trigger below (sums entries per transaction).
CREATE INDEX ledger_entries_txn_id_idx ON ledger_entries (txn_id);

-- -----------------------------------------------------------------------------
-- 5. Lending
-- -----------------------------------------------------------------------------
CREATE TABLE loan_requests (
    id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    borrower_id       bigint         NOT NULL REFERENCES users (id),
    amount            numeric(14,2)  NOT NULL CHECK (amount BETWEEN 5000 AND 5000000),
    purpose           text           NOT NULL CHECK (purpose IN
                        ('SCHOOL_FEES','RENT','BUSINESS_STOCK','MEDICAL','EQUIPMENT','TRAVEL','OTHER')),
    tenor_weeks       smallint       NOT NULL CHECK (tenor_weeks BETWEEN 1 AND 104),
    -- Flat total interest as a percentage of principal, over the whole tenor.
    interest_rate_pct numeric(5,2)   NOT NULL CHECK (interest_rate_pct >= 0 AND interest_rate_pct <= 40),
    status            request_status NOT NULL DEFAULT 'OPEN',
    funded_amount     numeric(14,2)  NOT NULL DEFAULT 0,
    version           integer        NOT NULL DEFAULT 0,
    created_at        timestamptz    NOT NULL DEFAULT now(),
    expires_at        timestamptz    NOT NULL,
    CONSTRAINT loan_requests_funded_within_amount CHECK (funded_amount BETWEEN 0 AND amount),
    CONSTRAINT loan_requests_funded_status CHECK (status <> 'FUNDED' OR funded_amount = amount),
    CONSTRAINT loan_requests_expiry_after_creation CHECK (expires_at > created_at)
);

CREATE TABLE loan_fundings (
    id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    loan_request_id bigint        NOT NULL REFERENCES loan_requests (id),
    lender_id       bigint        NOT NULL REFERENCES users (id),
    amount          numeric(14,2) NOT NULL CHECK (amount > 0),
    idempotency_key text          NOT NULL UNIQUE,
    ledger_txn_id   bigint        NOT NULL UNIQUE REFERENCES ledger_transactions (id),
    created_at      timestamptz   NOT NULL DEFAULT now()
);

CREATE TABLE loans (
    id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    loan_request_id   bigint        NOT NULL UNIQUE REFERENCES loan_requests (id),
    borrower_id       bigint        NOT NULL REFERENCES users (id),
    principal         numeric(14,2) NOT NULL CHECK (principal > 0),
    interest_rate_pct numeric(5,2)  NOT NULL CHECK (interest_rate_pct >= 0),
    tenor_weeks       smallint      NOT NULL CHECK (tenor_weeks > 0),
    platform_fee      numeric(14,2) NOT NULL CHECK (platform_fee >= 0),
    status            loan_status   NOT NULL DEFAULT 'ACTIVE',
    disbursed_at      timestamptz   NOT NULL,
    closed_at         timestamptz,
    CONSTRAINT loans_closed_after_disbursed CHECK (closed_at IS NULL OR closed_at >= disbursed_at)
);

CREATE TABLE repayment_schedules (
    id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    loan_id       bigint            NOT NULL REFERENCES loans (id),
    instalment_no smallint          NOT NULL CHECK (instalment_no > 0),
    due_date      date              NOT NULL,
    principal_due numeric(14,2)     NOT NULL CHECK (principal_due >= 0),
    interest_due  numeric(14,2)     NOT NULL CHECK (interest_due >= 0),
    amount_due    numeric(14,2)     NOT NULL,
    amount_paid   numeric(14,2)     NOT NULL DEFAULT 0,
    status        instalment_status NOT NULL DEFAULT 'PENDING',
    UNIQUE (loan_id, instalment_no),
    CONSTRAINT schedule_amount_is_sum   CHECK (amount_due = principal_due + interest_due),
    CONSTRAINT schedule_paid_in_range   CHECK (amount_paid BETWEEN 0 AND amount_due),
    CONSTRAINT schedule_paid_iff_status CHECK ((status = 'PAID') = (amount_paid = amount_due))
);

CREATE TABLE repayments (
    id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    loan_id         bigint        NOT NULL REFERENCES loans (id),
    schedule_id     bigint        NOT NULL REFERENCES repayment_schedules (id),
    payer_id        bigint        NOT NULL REFERENCES users (id),
    amount          numeric(14,2) NOT NULL CHECK (amount > 0),
    paid_at         timestamptz   NOT NULL DEFAULT now(),
    ledger_txn_id   bigint        NOT NULL UNIQUE REFERENCES ledger_transactions (id),
    idempotency_key text          NOT NULL UNIQUE
);

CREATE TABLE fees (
    id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    loan_id       bigint        NOT NULL REFERENCES loans (id),
    ledger_txn_id bigint        NOT NULL REFERENCES ledger_transactions (id),
    fee_type      text          NOT NULL CHECK (fee_type IN ('PLATFORM_SERVICE_FEE')),
    amount        numeric(14,2) NOT NULL CHECK (amount > 0),
    created_at    timestamptz   NOT NULL DEFAULT now()
);

-- -----------------------------------------------------------------------------
-- 6. Trust, disputes, notifications, audit
-- -----------------------------------------------------------------------------
CREATE TABLE trust_scores (
    user_id      bigint PRIMARY KEY REFERENCES users (id),
    score        smallint NOT NULL CHECK (score BETWEEN 300 AND 850),
    on_time_rate numeric(5,2) CHECK (on_time_rate BETWEEN 0 AND 100),  -- NULL = no history
    computed_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE disputes (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    loan_id     bigint         NOT NULL REFERENCES loans (id),
    raised_by   bigint         NOT NULL REFERENCES users (id),
    reason      text           NOT NULL,
    status      dispute_status NOT NULL DEFAULT 'OPEN',
    created_at  timestamptz    NOT NULL DEFAULT now(),
    resolved_at timestamptz,
    CONSTRAINT disputes_resolved_has_date
        CHECK ((status IN ('RESOLVED','REJECTED')) = (resolved_at IS NOT NULL))
);

CREATE TABLE notifications (
    id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id    bigint            NOT NULL REFERENCES users (id),
    type       notification_type NOT NULL,
    title      text              NOT NULL,
    body       text              NOT NULL,
    read_at    timestamptz,
    created_at timestamptz       NOT NULL DEFAULT now()
);

CREATE TABLE audit_logs (
    id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    actor_user_id bigint REFERENCES users (id),     -- NULL = system job
    action        text        NOT NULL,
    entity_type   text        NOT NULL,
    entity_id     bigint,
    details       jsonb       NOT NULL DEFAULT '{}'::jsonb,
    created_at    timestamptz NOT NULL DEFAULT now()
);

-- =============================================================================
-- 7. Triggers: business rules enforced inside the database
-- =============================================================================

-- 7.1 Ledger is append only (rule: no updates or deletes) ---------------------
CREATE FUNCTION trg_ledger_append_only() RETURNS trigger
    LANGUAGE plpgsql AS
$$
BEGIN
    RAISE EXCEPTION 'The ledger is append only: % on % is not allowed', TG_OP, TG_TABLE_NAME
        USING ERRCODE = 'integrity_constraint_violation';
END;
$$;

CREATE TRIGGER ledger_entries_append_only
    BEFORE UPDATE OR DELETE ON ledger_entries
    FOR EACH ROW EXECUTE FUNCTION trg_ledger_append_only();
CREATE TRIGGER ledger_entries_no_truncate
    BEFORE TRUNCATE ON ledger_entries
    FOR EACH STATEMENT EXECUTE FUNCTION trg_ledger_append_only();
CREATE TRIGGER ledger_transactions_append_only
    BEFORE UPDATE OR DELETE ON ledger_transactions
    FOR EACH ROW EXECUTE FUNCTION trg_ledger_append_only();
CREATE TRIGGER ledger_transactions_no_truncate
    BEFORE TRUNCATE ON ledger_transactions
    FOR EACH STATEMENT EXECUTE FUNCTION trg_ledger_append_only();

-- 7.2 Every ledger transaction must sum to zero (double entry) ----------------
-- Deferred to COMMIT so that the legs of one transaction can be inserted one by one.
CREATE FUNCTION trg_ledger_balanced() RETURNS trigger
    LANGUAGE plpgsql AS
$$
DECLARE
    v_sum numeric;
BEGIN
    SELECT sum(amount) INTO v_sum FROM ledger_entries WHERE txn_id = NEW.txn_id;
    IF v_sum <> 0 THEN
        RAISE EXCEPTION 'Ledger transaction % does not balance (sum of entries = %)', NEW.txn_id, v_sum
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NULL;
END;
$$;

CREATE CONSTRAINT TRIGGER ledger_entries_balanced
    AFTER INSERT ON ledger_entries
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION trg_ledger_balanced();

-- 7.3 Keep wallets.balance equal to the sum of its ledger entries --------------
-- The CHECK constraint wallets_balance_non_negative then rejects any entry that
-- would overdraw a wallet.
CREATE FUNCTION trg_ledger_apply_balance() RETURNS trigger
    LANGUAGE plpgsql AS
$$
BEGIN
    UPDATE wallets
       SET balance = balance + NEW.amount
     WHERE id = NEW.wallet_id;
    RETURN NULL;
END;
$$;

CREATE TRIGGER ledger_entries_apply_balance
    AFTER INSERT ON ledger_entries
    FOR EACH ROW EXECUTE FUNCTION trg_ledger_apply_balance();

-- Any update of a wallet bumps its version and timestamp (optimistic locking).
CREATE FUNCTION trg_wallet_touch() RETURNS trigger
    LANGUAGE plpgsql AS
$$
BEGIN
    NEW.version    := OLD.version + 1;
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

CREATE TRIGGER wallets_touch
    BEFORE UPDATE ON wallets
    FOR EACH ROW EXECUTE FUNCTION trg_wallet_touch();

-- 7.4 Loan request rules --------------------------------------------------------
CREATE FUNCTION trg_loan_request_before_insert() RETURNS trigger
    LANGUAGE plpgsql AS
$$
BEGIN
    IF NEW.amount > copay_kyc_limit() AND NOT copay_is_kyc_verified(NEW.borrower_id) THEN
        RAISE EXCEPTION 'KYC verification is required to borrow more than % NGN', copay_kyc_limit()
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER loan_requests_before_insert
    BEFORE INSERT ON loan_requests
    FOR EACH ROW EXECUTE FUNCTION trg_loan_request_before_insert();

-- 7.5 Funding rules: not own request, KYC limit, no over funding ---------------
-- Locks the loan request row (FOR UPDATE) so that concurrent lenders are
-- serialised on that request and the funded total can never exceed the amount.
CREATE FUNCTION trg_loan_funding_before_insert() RETURNS trigger
    LANGUAGE plpgsql AS
$$
DECLARE
    r loan_requests%ROWTYPE;
BEGIN
    SELECT * INTO r FROM loan_requests WHERE id = NEW.loan_request_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Loan request % does not exist', NEW.loan_request_id;
    END IF;
    IF r.status <> 'OPEN' THEN
        RAISE EXCEPTION 'Loan request % is not open (status %)', r.id, r.status
            USING ERRCODE = 'check_violation';
    END IF;
    IF r.borrower_id = NEW.lender_id THEN
        RAISE EXCEPTION 'A user cannot lend to their own request'
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.amount > copay_kyc_limit() AND NOT copay_is_kyc_verified(NEW.lender_id) THEN
        RAISE EXCEPTION 'KYC verification is required to lend more than % NGN', copay_kyc_limit()
            USING ERRCODE = 'check_violation';
    END IF;
    IF r.funded_amount + NEW.amount > r.amount THEN
        RAISE EXCEPTION 'Funding of % would exceed the requested amount (remaining %)',
            NEW.amount, r.amount - r.funded_amount
            USING ERRCODE = 'check_violation';
    END IF;

    UPDATE loan_requests
       SET funded_amount = funded_amount + NEW.amount,
           status  = CASE WHEN funded_amount + NEW.amount = amount
                          THEN 'FUNDED'::request_status ELSE status END,
           version = version + 1
     WHERE id = r.id;
    RETURN NEW;
END;
$$;

CREATE TRIGGER loan_fundings_before_insert
    BEFORE INSERT ON loan_fundings
    FOR EACH ROW EXECUTE FUNCTION trg_loan_funding_before_insert();

-- 7.6 Repayment rules: oldest unpaid instalment first, no overpayment ---------
CREATE FUNCTION trg_repayment_before_insert() RETURNS trigger
    LANGUAGE plpgsql AS
$$
DECLARE
    s repayment_schedules%ROWTYPE;
BEGIN
    SELECT * INTO s FROM repayment_schedules WHERE id = NEW.schedule_id FOR UPDATE;
    IF NOT FOUND OR s.loan_id <> NEW.loan_id THEN
        RAISE EXCEPTION 'Schedule % does not belong to loan %', NEW.schedule_id, NEW.loan_id;
    END IF;
    PERFORM 1 FROM loans WHERE id = NEW.loan_id AND borrower_id = NEW.payer_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Payer % is not the borrower of loan %', NEW.payer_id, NEW.loan_id;
    END IF;
    IF EXISTS (SELECT 1 FROM repayment_schedules
                WHERE loan_id = s.loan_id
                  AND instalment_no < s.instalment_no
                  AND status <> 'PAID') THEN
        RAISE EXCEPTION 'Repayments must clear the oldest unpaid instalment first (loan %, instalment %)',
            s.loan_id, s.instalment_no USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.amount > s.amount_due - s.amount_paid THEN
        RAISE EXCEPTION 'Repayment of % exceeds the outstanding % on instalment %',
            NEW.amount, s.amount_due - s.amount_paid, s.id USING ERRCODE = 'check_violation';
    END IF;

    UPDATE repayment_schedules
       SET amount_paid = amount_paid + NEW.amount,
           status = CASE WHEN amount_paid + NEW.amount = amount_due
                         THEN 'PAID'::instalment_status ELSE 'PARTIAL'::instalment_status END
     WHERE id = s.id;

    IF NOT EXISTS (SELECT 1 FROM repayment_schedules WHERE loan_id = s.loan_id AND status <> 'PAID') THEN
        UPDATE loans SET status = 'REPAID', closed_at = NEW.paid_at WHERE id = s.loan_id;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER repayments_before_insert
    BEFORE INSERT ON repayments
    FOR EACH ROW EXECUTE FUNCTION trg_repayment_before_insert();

-- =============================================================================
-- 8. Back office helpers
-- =============================================================================

-- Reconciliation: cached balance versus the ledger. A healthy system returns no
-- rows from:  SELECT * FROM wallet_reconciliation WHERE difference <> 0;
CREATE VIEW wallet_reconciliation AS
SELECT w.id AS wallet_id,
       w.kind,
       w.balance AS cached_balance,
       COALESCE(SUM(e.amount), 0)::numeric(14,2) AS ledger_sum,
       (w.balance - COALESCE(SUM(e.amount), 0))::numeric(14,2) AS difference
  FROM wallets w
  LEFT JOIN ledger_entries e ON e.wallet_id = w.id
 GROUP BY w.id, w.kind, w.balance;

-- Nightly job: flag late instalments and default loans with 4 or more of them.
CREATE FUNCTION mark_overdue(p_as_of date DEFAULT current_date)
    RETURNS TABLE (instalments_marked bigint, loans_defaulted bigint)
    LANGUAGE plpgsql AS
$$
DECLARE
    v_marked bigint;
    v_defaulted bigint;
BEGIN
    UPDATE repayment_schedules
       SET status = 'OVERDUE'
     WHERE due_date < p_as_of AND status IN ('PENDING', 'PARTIAL');
    GET DIAGNOSTICS v_marked = ROW_COUNT;

    UPDATE loans l
       SET status = 'DEFAULTED'
     WHERE l.status = 'ACTIVE'
       AND (SELECT count(*) FROM repayment_schedules s
             WHERE s.loan_id = l.id AND s.status = 'OVERDUE') >= 4;
    GET DIAGNOSTICS v_defaulted = ROW_COUNT;

    RETURN QUERY SELECT v_marked, v_defaulted;
END;
$$;
